import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-105: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short105', durationInSeconds: 31.0, fps: 30, width: 1080, height: 1920 };


const B1 = secToFrame(4.8);
const B2 = secToFrame(8.0);
const B3 = secToFrame(13.0);
const B4 = secToFrame(16.6);
const B5 = secToFrame(24.5);
const CTA = secToFrame(29.0);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short105: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-105/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="VOICE AGENT PRICING" lines={[{ text: 'XAI 8¢ / MIN' },{ text: 'OPENAI 5¢ / MIN', accent: true }]} />
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="Grok Voice 3.0" tagline="xAI's voice agent API." chip="8¢ / MIN" at={B1 + 4}>
          <Panel>
            <Line k="price / minute" v="$0.08" good />
            <Line k="price / hour" v="$4.80" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="GPT Live 1" tagline="OpenAI's voice model." chip="5¢ / MIN" at={B2 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="price / minute" v="$0.05" good />
            <Line k="billing" v="per second" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="The gap" tagline="xAI is 60% higher." chip="1.6X" at={B3 + 4} chipColor={COLORS.danger}>
          <Panel>
            <Line k="xAI" v="$0.08" bad />
            <Line k="OpenAI" v="$0.05" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B5}>
        <ToolCard name="The fine print" tagline="OpenAI bills model + tools extra." chip="CHECK" at={B4 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="voice session" v="$0.05 / min" />
            <Line k="model + tools" v="billed extra" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="The takeaway" tagline="Compare your total, not the rate." chip="VERDICT" at={B5 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Grok Voice 3.0" v="$0.08 / min" />
            <Line k="GPT Live 1" v="$0.05 / min" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-105/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="VOICE AGENT PRICING" lines={[{ text: 'XAI 8¢ / MIN' },{ text: 'OPENAI 5¢ / MIN', accent: true }]} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Check your total, not the rate.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short105;
